	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, requisicaoDBTypes, false, strmangle.SetComplement(requisicaoPrimaryKeyColumns, requisicaoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*Requisicao{
		{&b, &c},
		{&d, &e},
	}

